diff --git a/src/web/kit/layouts/top-bar/TopBar.module.css b/src/web/kit/layouts/top-bar/TopBar.module.css
index 3a7fcea6..92b8ed56 100644
--- a/src/web/kit/layouts/top-bar/TopBar.module.css
+++ b/src/web/kit/layouts/top-bar/TopBar.module.css
@@ -102,4 +102,13 @@
   .theme {
     justify-self: start;
   }
+
+  /* The field takes the whole row, so its placeholder ("Rule ID, node, SHA or path") is read whole. */
+  .search {
+    flex-wrap: wrap;
+  }
+
+  .field {
+    flex-basis: 100%;
+  }
 }
diff --git a/src/web/kit/patterns/data-table/DataTable.module.css b/src/web/kit/patterns/data-table/DataTable.module.css
index 374fc253..9bfaa9d5 100644
--- a/src/web/kit/patterns/data-table/DataTable.module.css
+++ b/src/web/kit/patterns/data-table/DataTable.module.css
@@ -5,7 +5,7 @@
   box-sizing: border-box;
   min-width: 0;
   max-width: 100%;
-  max-height: var(--data-table-max-height, 36rem);
+  max-height: var(--data-table-max-height, none);
   overflow: auto;
   font-family: var(--font-sans);
   font-size: var(--text-14);
diff --git a/src/web/kit/patterns/data-table/DataTable.tsx b/src/web/kit/patterns/data-table/DataTable.tsx
index 15e597ee..6e8de45b 100644
--- a/src/web/kit/patterns/data-table/DataTable.tsx
+++ b/src/web/kit/patterns/data-table/DataTable.tsx
@@ -58,7 +58,10 @@ export interface DataTableProps<Row extends { id: string }> {
   retrying?: boolean;
   /** Shown when there are no rows. */
   empty?: DataTableEmpty;
-  /** Past this height the table scrolls inside its own frame and the header stays put. A CSS length. */
+  /**
+   * Past this height the table scrolls inside its own frame and the header stays put. A CSS length. With none, the
+   * table is as tall as its rows: a cap is the caller's choice, never a default that hides rows.
+   */
   maxHeight?: string;
 }

@@ -104,7 +107,7 @@ export function DataTable<Row extends { id: string }>({
                 <th
                   key={column.id}
                   scope="col"
-                  className={column.numeric ? `${styles.th} ${styles.num}` : styles.th}
+                  className={column.numeric ? styles.num : undefined}
                   data-numeric={column.numeric ? 'true' : undefined}
                   aria-sort={sorted}
                 >
diff --git a/src/web/kit/patterns/request-log/RequestLog.module.css b/src/web/kit/patterns/request-log/RequestLog.module.css
index 47bcbd67..45a4d4a7 100644
--- a/src/web/kit/patterns/request-log/RequestLog.module.css
+++ b/src/web/kit/patterns/request-log/RequestLog.module.css
@@ -121,7 +121,9 @@
   white-space: nowrap;
 }

-.table thead th.num {
+/* As specific as `.table td` above, so a duration sits right under its right-aligned header. */
+.table th.num,
+.table td.num {
   text-align: right;
 }

@@ -163,7 +165,13 @@
   }

   .path {
-    min-width: 6rem;
+    min-width: 5rem;
+  }
+
+  /* The header and "not recorded" wrap at their spaces, so the five columns fit the frame. */
+  .table thead th,
+  .table td.num {
+    white-space: normal;
   }
 }

